insert into public.action_definitions(id,version,data) values('BUILD_LEADERSHIP_EXPERIENCE','2.0.0','{"id":"BUILD_LEADERSHIP_EXPERIENCE","title":"작은 팀의 결과를 책임지세요.","detail":"30일 안에 3명 규모 프로젝트를 제안하고 역할과 마감일을 문서화하세요.","trait":"leadership","delta":18}'::jsonb) on conflict do nothing;
insert into public.action_definitions(id,version,data) values('BUILD_EXTERNAL_VISIBILITY','2.0.0','{"id":"BUILD_EXTERNAL_VISIBILITY","title":"성과를 회사 밖으로 꺼내세요.","detail":"14일 안에 민감정보를 제거한 문제·해결·수치 사례를 1편 공개하세요.","trait":"external_visibility","delta":20}'::jsonb) on conflict do nothing;
insert into public.action_definitions(id,version,data) values('BUILD_SKILL','2.0.0','{"id":"BUILD_SKILL","title":"직무를 하나 고르고 증거를 만드세요.","detail":"30일 안에 목표 공고 10개를 비교하고 공통 기술로 결과물 1개를 완성하세요.","trait":"specialist_orientation","delta":15}'::jsonb) on conflict do nothing;
insert into public.action_definitions(id,version,data) values('GAIN_EXPERIENCE','2.0.0','{"id":"GAIN_EXPERIENCE","title":"지원보다 먼저 작은 실무를 완주하세요.","detail":"6주 안에 실제 사용자가 있는 프로젝트나 유급 단기 업무를 완수하세요.","trait":"execution","delta":15}'::jsonb) on conflict do nothing;
insert into public.action_definitions(id,version,data) values('VALIDATE_BUSINESS','2.0.0','{"id":"VALIDATE_BUSINESS","title":"퇴사 전에 고객부터 확인하세요.","detail":"2주 동안 잠재 고객 10명을 인터뷰하고 유료 의향 3건을 확인하세요.","trait":"entrepreneurship","delta":12}'::jsonb) on conflict do nothing;
insert into public.action_definitions(id,version,data) values('BUILD_RUNWAY','2.0.0','{"id":"BUILD_RUNWAY","title":"선택할 수 있는 생활비를 확보하세요.","detail":"이번 주 고정지출을 정리하고 6개월 비상자금 계획을 세우세요.","trait":"stability","delta":12}'::jsonb) on conflict do nothing;
insert into public.action_definitions(id,version,data) values('DOCUMENT_IMPACT','2.0.0','{"id":"DOCUMENT_IMPACT","title":"업무량 대신 결과를 기록하세요.","detail":"이번 주 성과 3건을 전후 수치와 담당 범위로 정리하세요.","trait":"achievement_orientation","delta":10}'::jsonb) on conflict do nothing;
insert into public.action_definitions(id,version,data) values('NEGOTIATE','2.0.0','{"id":"NEGOTIATE","title":"협상 자료를 만드세요.","detail":"30일 안에 시장 공고 10개와 본인 성과를 1장으로 정리하세요.","trait":"persuasion","delta":12}'::jsonb) on conflict do nothing;
insert into public.action_definitions(id,version,data) values('BUILD_NETWORK','2.0.0','{"id":"BUILD_NETWORK","title":"연락할 사람을 만드세요.","detail":"매주 동종 직무 1명과 업무 이야기를 나누고 배운 점을 기록하세요.","trait":"networking","delta":12}'::jsonb) on conflict do nothing;
insert into public.action_definitions(id,version,data) values('LEARN','2.0.0','{"id":"LEARN","title":"학습을 일정에 고정하세요.","detail":"4주간 주 3시간을 배정하고 매주 결과물로 검증하세요.","trait":"learning_speed","delta":10}'::jsonb) on conflict do nothing;
insert into public.action_definitions(id,version,data) values('ACTION_11','2.0.0','{"id":"ACTION_11","title":"분석 가설을 검증하세요","detail":"앞으로 14일 동안 ''분석 가설을 검증하기''를 실행하고 결과와 다음 수정 사항을 한 페이지로 기록하세요.","trait":"analytical","delta":8}'::jsonb) on conflict do nothing;
insert into public.action_definitions(id,version,data) values('ACTION_12','2.0.0','{"id":"ACTION_12","title":"초안 3개를 비교하세요","detail":"앞으로 14일 동안 ''초안 3개를 비교하기''를 실행하고 결과와 다음 수정 사항을 한 페이지로 기록하세요.","trait":"creativity","delta":8}'::jsonb) on conflict do nothing;
insert into public.action_definitions(id,version,data) values('ACTION_13','2.0.0','{"id":"ACTION_13","title":"완료 기준을 정하세요","detail":"앞으로 14일 동안 ''완료 기준을 정하기''를 실행하고 결과와 다음 수정 사항을 한 페이지로 기록하세요.","trait":"persistence","delta":8}'::jsonb) on conflict do nothing;
insert into public.action_definitions(id,version,data) values('ACTION_14','2.0.0','{"id":"ACTION_14","title":"혼자 결정할 범위를 정하세요","detail":"앞으로 14일 동안 ''혼자 결정할 범위를 정하기''를 실행하고 결과와 다음 수정 사항을 한 페이지로 기록하세요.","trait":"stability","delta":8}'::jsonb) on conflict do nothing;
