g":null,"templateId":"TRANSITION"},{"id":"LEADER","priority":81,"when":{"all":[{"field":"leadership","op":"gte","value":65},{"field":"external_visibility","op":"gte","value":60}]},"actionIds":["DOCUMENT_IMPACT"],"ceiling":null,"templateId":"LEADER"}],"actions":[{"id":"BUILD_LEADERSHIP_EXPERIENCE","title":"작은 팀의 결과를 책임지세요.","detail":"30일 안에 3명 규모 프로젝트를 제안하고 역할과 마감일을 문서화하세요.","trait":"leadership","delta":18},{"id":"BUILD_EXTERNAL_VISIBILITY","title":"성과를 회사 밖으로 꺼내세요.","detail":"14일 안에 민감정보를 제거한 문제·해결·수치 사례를 1편 공개하세요.","trait":"external_visibility","delta":20},{"id":"BUILD_SKILL","title":"직무를 하나 고르고 증거를 만드세요.","detail":"30일 안에 목표 공고 10개를 비교하고 공통 기술로 결과물 1개를 완성하세요.","trait":"specialist_orientation","delta":15},{"id":"GAIN_EXPERIENCE","title":"지원보다 먼저 작은 실무를 완주하세요.","detail":"6주 안에 실제 사용자가 있는 프로젝트나 유급 단기 업무를 완수하세요.","trait":"execution","delta":15},{"id":"VALIDATE_BUSINESS","title":"퇴사 전에 고객부터 확인하세요.","detail":"2주 동안 잠재 고객 10명을 인터뷰하고 유료 의향 3건을 확인하세요.","trait":"entrepreneurship","delta":12},{"id":"BUILD_RUNWAY","title":"선택할 수 있는 생활비를 확보하세요.","detail":"이번 주 고정지출을 정리하고 6개월 비상자금 계획을 세우세요.","trait":"stability","delta":12},{"id":"DOCUMENT_IMPACT","title":"업무량 대신 결과를 기록하세요.","detail":"이번 주 성과 3건을 전후 수치와 담당 범위로 정리하세요.","trait":"achievement_orientation","delta":10},{"id":"NEGOTIATE","title":"협상 자료를 만드세요.","detail":"30일 안에 시장 공고 10개와 본인 성과를 1장으로 정리하세요.","trait":"persuasion","delta":12},{"id":"BUILD_NETWORK","title":"연락할 사람을 만드세요.","detail":"매주 동종 직무 1명과 업무 이야기를 나누고 배운 점을 기록하세요.","trait":"networking","delta":12},{"id":"LEARN","title":"학습을 일정에 고정하세요.","detail":"4주간 주 3시간을 배정하고 매주 결과물로 검증하세요.","trait":"learning_speed","delta":10},{"id":"ACTION_11","title":"분석 가설을 검증하세요","detail":"앞으로 14일 동안 ''분석 가설을 검증하기''를 실행하고 결과와 다음 수정 사항을 한 페이지로 기록하세요.","trait":"analytical","delta":8},{"id":"ACTION_12","title":"초안 3개를 비교하세요","detail":"앞으로 14일 동안 ''초안 3개를 비교하기''를 실행하고 결과와 다음 수정 사항을 한 페이지로 기록하세요.","trait":"creativity","delta":8},{"id":"ACTION_13","title":"완료 기준을 정하세요","detail":"앞으로 14일 동안 ''완료 기준을 정하기''를 실행하고 결과와 다음 수정 사항을 한 페이지로 기록하세요.","trait":"persistence","delta":8},{"id":"ACTION_14","title":"혼자 결정할 범위를 정하세요","detail":"앞으로 14일 동안 ''혼자 결정할 범위를 정하기''를 실행하고 결과와 다음 수정 사항을 한 페이지로 기록하세요.","trait":"stability","delta":8},{"id":"ACTION_15","title":"발표를 녹화하세요","detail":"앞으로 14일 동안 ''발표를 녹화하기''를 실행하고 결과와 다음 수정 사항을 한 페이지로 기록하세요.","trait":"independence","delta":8},{"id":"ACTION_16","title":"회의 결론을 문서화하세요","detail":"앞으로 14일 동안 ''회의 결론을 문서화하기''를 실행하고 결과와 다음 수정 사항을 한 페이지로 기록하세요.","trait":"leadership","delta":8},{"id":"ACTION_17","title":"위험 한도를 정하세요","detail":"앞으로 14일 동안 ''위험 한도를 정하기''를 실행하고 결과와 다음 수정 사항을 한 페이지로 기록하세요.","trait":"social_influence","delta":8},{"id":"ACTION_18","title":"소득원을 점검하세요","detail":"앞으로 14일 동안 ''소득원을 점검하기''를 실행하고 결과와 다음 수정 사항을 한 페이지로 기록하세요.","trait":"communication","delta":8},{"id":"ACTION_19","title":"피드백을 요청하세요","detail":"앞으로 14일 동안 ''피드백을 요청하기''를 실행하고 결과와 다음 수정 사항을 한 페이지로 기록하세요.","trait":"risk_tolerance","delta":8},{"id":"ACTION_20","title":"감정 기록을 남기세요","detail":"앞으로 14일 동안 ''감정 기록을 남기기''를 실행하고 결과와 다음 수정 사항을 한 페이지로 기록하세요.","trait":"money_orientation","delta":8},{"id":"ACTION_21","title":"약속을 지키는 구조를 만드세요","detail":"앞으로 14일 동안 ''약속을 지키는 구조를 만드기''를 실행하고 결과와 다음 수정 사항을 한 페이지로 기록하세요.","trait":"achievement_orientation","delta":8},{"id":"ACTION_22","title":"다른 직무를 체험하세요","detail":"앞으로 14일 동안 ''다른 직무를 체험하기''를 실행하고 결과와 다음 수정 사항을 한 페이지로 기록하세요.","trait":"recognition_need","delta":8},{"id":"ACTION_23","title":"인수인계 문서를 만드세요","detail":"앞으로 14일 동안 ''인수인계 문서를 만드기''를 실행하고 결과와 다음 수정 사항을 한 페이지로 기록하세요.","trait":"emotional_sensitivity","delta":8},{"id":"ACTION_24","title":"일정 오차를 측정하세요","detail":"앞으로 14일 동안 ''일정 오차를 측정하기''를 실행하고 결과와 다음 수정 사항을 한 페이지로 기록하세요.","trait":"relationship_stability","delta":8},{"id":"ACTION_25","title":"책임 범위를 합의하세요","detail":"앞으로 14일 동안 ''책임 범위를 합의하기''를 실행하고 결과와 다음 수정 사항을 한 페이지로 기록하세요.","trait":"adaptability","delta":8},{"id":"ACTION_26","title":"전문 주제를 좁히세요","detail":"앞으로 14일 동안 ''전문 주제를 좁히기''를 실행하고 결과와 다음 수정 사항을 한 페이지로 기록하세요.","trait":"career_mobility","delta":8},{"id":"ACTION_27","title":"위임할 업무를 정하세요","detail":"앞으로 14일 동안 ''위임할 업무를 정하기''를 실행하고 결과와 다음 수정 사항을 한 페이지로 기록하세요.","trait":"entrepreneurship","delta":8},{"id":"ACTION_28","title":"회복 시간을 확보하세요","detail":"앞으로 14일 동안 ''회복 시간을 확보하기''를 실행하고 결과와 다음 수정 사항을 한 페이지로 기록하세요.","trait":"organization_fit","delta":8},{"id":"ACTION_29","title":"비교 기준을 정하세요","detail":"앞으로 14일 동안 ''비교 기준을 정하기''를 실행하고 결과와 다음 수정 사항을 한 페이지로 기록하세요.","trait":"execution","delta":8},{"id":"ACTION_30","title":"결정 기한을 정하세요","detail":"앞으로 14일 동안 ''결정 기한을 정하기''를 실행하고 결과와 다음 수정 사항을 한 페이지로 기록하세요.","trait":"planning","delta":8}],"levels":[{"id":1,"label":"Junior"},{"id":2,"label":"Professional"},{"id":3,"label":"Senior"},{"id":4,"label":"Team / Expert Lead"},{"id":5,"label":"Executive / Principal"}],"products":[{"id":"career-basic","label":"Career Basic","price":0,"enabled":true},{"id":"career-full","label":"Career Full","price":9900,"enabled":true},{"id":"relationship","label":"Relationship","price":0,"enabled":false},{"id":"life-full","label":"Life Full Report","price":0,"enabled":false}],"scenarioConfig":{"levelGates":[{"level":4,"when":{"field":"leadership","op":"gte","value":50}},{"level":5,"when":{"all":[{"field":"leadership","op":"gte","value":65},{"field":"external_visibility","op":"gte","value":60}]}}],"baseCeiling":3,"improvedDelta":1,"aggressiveDelta":2,"criticalOffset":2,"retirementFloor":55,"retirementOffset":14},"domainWeights":{"career":{"execution":0.3,"specialist_orientation":0.25,"leadership":0.25,"external_visibility":0.2},"money":{"money_orientation":0.5,"planning":0.5},"relationship":{"communication":0.5,"relationship_stability":0.5},"business":{"entrepreneurship":0.4,"risk_tolerance":0.3,"execution":0.3}}},"templates":{"version":"2.0.0","interpretations":[{"id":"ENTRY","variant":"direct","headline":"직업 진입이 먼저입니다.","judgement":"직업 진입이 먼저입니다.","explanation":"현재 구직 상태이며 경력은 {{experienceYears}}년입니다. 지금의 병목은 적성 이름이 아니라, 채용 담당자가 확인할 실무 증거입니다.","criticism":"어떤 직업이 운명인지 고민하는 동안 지원할 결과물은 늘지 않습니다. 관심 직무를 하나로 좁히세요.","risk":"준비 기간만 길어지고 실제 업무를 끝낸 기록이 없으면 다음 지원도 같은 질문 앞에서 멈춥니다.","recommendation":"직무를 하나 고르고 증거를 만드세요.","action":"30일 안에 목표 공고 10개를 비교하고 공통 기술로 결과물 1개를 완성하세요.","scenario":"기술 결과물과 작은 실무 경험을 확보한다는 조건에서 리드급 또는 상위 전문가 개선 경로를 검토합니다. 첫 목표는 직급이 아니라 직무 진입입니다.","closing":"다음 분석에서는 의지가 아니라 완료한 증거를 입력하세요.","direct":{"criticism":"연차가 늘어나는 것과 책임의 범위가 커지는 건 달라. 기다리는 것만으로 다음 역할의 근거가 생기지는 않아.","risk":"같은 기록만 더 쌓으면 숙련은 늘어도 지금 막히는 지점이 남을 가능성이 높아.","scenario":"행동을 끝내고 성과로 입증하면, 현재 경로에서 리드급 또는 상위 전문가 역할로 넘어갈 근거가 생겨. 기회와 지속 실행을 전제로 경로를 다시 봐야 해.","closing":"다음에는 의지보다 완료한 증거를 기록해.","judgement":"지금은 직업 진입부터 해야 해.","explanation":"{{experienceYears}}년 경력. 먼저 봐야 할 건 적성 이름보다 실제 업무를 끝낸 증거야.","action":"30일 안에 목표 공고 10개를 비교하고, 공통 기술로 결과물 하나를 완성해."}},{"id":"INVISIBLE_EXPERT","variant":"direct","headline":"실무는 쌓였는데, 당신의 영향력은 회사 안에 갇혀 있습니다.","judgement":"실무는 쌓였는데, 당신의 영향력은 회사 안에 갇혀 있습니다.","explanation":"{{experienceYears}}년 경력으로 실행력은 {{execution}}점입니다. 반면 리더십 {{leadership}}점, 외부 가시성 {{external_visibility}}점으로 성과를 타인에게 증명하는 축이 약합니다.","criticism":"혼자 해결한 일이 많아도, 남들이 당신을 따라 일한 경험이 없다면 상위 역할의 증거가 되지 않습니다. 회사 이름만 바꾸는 것으로는 이 격차가 사라지지 않습니다.","risk":"연봉을 올려 이직하더라도 같은 개인 기여자 역할에 머물면 현재 모형의 핵심 실무 병목이 이어집니다.","recommendation":"작은 팀의 결과를 책임지세요.","action":"30일 안에 3명 규모 프로젝트를 제안하고 역할과 마감일을 문서화하세요.","scenario":"팀의 결과를 책임진 경험과 외부 공개 성과를 함께 쌓으면 리드급 또는 상위 전문가 경로를 검토할 근거가 생깁니다. 적극 개선에는 지속적인 역할 확대가 추가로 필요합니다.","closing":"다음 분석에서는 의지가 아니라 완료한 증거를 입력하세요.","direct":{"criticism":"연차가 늘어나는 것과 책임의 범위가 커지는 건 달라. 기다리는 것만으로 다음 역할의 근거가 생기지는 않아.","risk":"같은 기록만 더 쌓으면 숙련은 늘어도 지금 막히는 지점이 남을 가능성이 높아.","scenario":"행동을 끝내고 성과로 입증하면, 현재 경로에서 리드급 또는 상위 전문가 역할로 넘어갈 근거가 생겨. 기회와 지속 실행을 전제로 경로를 다시 봐야 해.","closing":"다음에는 의지보다 완료한 증거를 기록해.","judgement":"경력은 쌓였어. 그런데 영향력은 아직 회사 안에 갇혀 있어.","explanation":"{{experienceYears}}년 경력에 실행력은 {{execution}}점이야. 반면 리더십 {{leadership}}점, 외부 가시성 {{external_visibility}}점. 일을 해낸 기록에 비해 사람을 이끌고 외부에서 인정받은 근거가 약해.","action":"작은 프로젝트의 역할과 마감일을 직접 정하고 팀의 결과를 책임져. 회사 밖에는 공개할 수 있는 성과 사례부터 남겨."}},{"id":"MANAGER_WINDOW","variant":"direct","headline":"경력 연수만으로 관리자가 되지는 않습니다.","judgement":"경력 연수만으로 관리자가 되지는 않습니다.","explanation":"{{age}}세, {{experienceYears}}년 경력이며 현재 리딩 기록은 {{managementExperienceLabel}}입니다. 쌓인 연차와 실제 리딩 경험 사이의 차이가 이번 판정의 핵심입니다.","criticism":"회의에 오래 참석한 것과 사람에게 일을 맡기고 결과를 책임진 것은 다릅니다. 직함을 기다리지 말고 리딩 범위부터 확보하세요.","risk":"현재 역할만 유지하면 숙련은 늘어도 관리자 전환에 필요한 위임·피드백·책임의 기록은 남지 않습니다.","recommendation":"작은 팀의 결과를 책임지세요.","action":"30일 안에 3명 규모 프로젝트를 제안하고 역할과 마감일을 문서화하세요.","scenario":"작은 프로젝트에서 일정·인원·성과를 책임지는 경험을 확보하면 리드급 또는 상위 전문가 전환을 검토할 수 있습니다. Critical Age는 이를 확인할 계획상 점검일입니다.","closing":"다음 분석에서는 의지가 아니라 완료한 증거를 입력하세요.","direct":{"criticism":"연차가 늘어나는 것과 책임의 범위가 커지는 건 달라. 기다리는 것만으로 다음 역할의 근거가 생기지는 않아.","risk":"같은 기록만 더 쌓으면 숙련은 늘어도 지금 막히는 지점이 남을 가능성이 높아.","scenario":"행동을 끝내고 성과로 입증하면, 현재 경로에서 리드급 또는 상위 전문가 역할로 넘어갈 근거가 생겨. 기회와 지속 실행을 전제로 경로를 다시 봐야 해.","closing":"다음에는 의지보다 완료한 증거를 기록해.","judgement":"경력이 부족한 게 아니야. 이끈 기록이 부족해.","explanation":"{{age}}세, {{experienceYears}}년 경력. 현재 리딩 기록은 {{managementExperienceLabel}}. 연차와 실제로 책임진 범위 사이에 차이가 있어.","action":"프로젝트 리더를 맡든 작은 팀의 결과를 책임지든, 사람을 움직여본 기록부터 만들어."}},{"id":"LOW_LEAD","variant":"direct","headline":"혼자 잘하는 것과 팀의 결과를 만드는 것은 다릅니다.","judgement":"혼자 잘하는 것과 팀의 결과를 만드는 것은 다릅니다.","explanation":"리딩 기록 {{managementExperienceLabel}}과 행동 입력을 반영한 리더십 점수는 {{leadership}}점입니다. 상위 역할을 원한다면 개인 산출물 외의 증거가 필요합니다.","criticism":"시간이 해결해 줄 거라는 기대는 실행 계획이 아닙니다.","risk":"같은 행동을 반복하면 현재 병목이 남을 수 있습니다.","recommendation":"작은 팀의 결과를 책임지세요.","action":"30일 안에 3명 규모 프로젝트를 제안하고 역할과 마감일을 문서화하세요.","scenario":"행동을 완료하고 성과로 입증한다는 가정에서 개선 경로를 비교합니다.","closing":"다음 분석에서는 의지가 아니라 완료한 증거를 입력하세요.","direct":{"judgement":"혼자 잘하는 것과 팀의 결과를 만드는 건 달라.","explanation":"리딩 기록은 {{managementExperienceLabel}}, 리더십 점수는 {{leadership}}점이야. 상위 역할을 원하면 혼자 만든 산출물 말고 다른 증거가 필요해.","action":"30일 안에 3명 규모 프로젝트를 제안하고, 네 역할과 마감일을 문서로 남겨.","criticism":"시간이 해결해 준다는 기대는 계획이 아니야. 기다리는 동안 기록은 늘지 않아.","risk":"같은 행동을 반복하면 지금 막히는 지점이 그대로 남을 가능성이 높아.","scenario":"행동을 끝내고 성과로 입증하면 개선 경로를 다시 비교할 수 있어.","closing":"다음에는 의지 말고 완료한 증거를 기록해."}},{"id":"LOW_VISIBLE","variant":"direct","headline":"회사 밖에 보여줄 결과가 부족합니다.","judgement":"회사 밖에 보여줄 결과가 부족합니다.","explanation":"외부 공개 성과 입력은 10점 중 {{visibility}}점입니다. 실력이 없다는 뜻이 아니라 외부에서 검증할 통로가 적다는 뜻입니다.","criticism":"시간이 해결해 줄 거라는 기대는 실행 계획이 아닙니다.","risk":"같은 행동을 반복하면 현재 병목이 남을 수 있습니다.","recommendation":"성과를 회사 밖으로 꺼내세요.","action":"14일 안에 민감정보를 제거한 문제·해결·수치 사례를 1편 공개하세요.","scenario":"행동을 완료하고 성과로 입증한다는 가정에서 개선 경로를 비교합니다.","closing":"다음 분석에서는 의지가 아니라 완료한 증거를 입력하세요.","direct":{"judgement":"회사 밖에 내보일 결과가 부족해.","explanation":"외부 공개 성과 입력은 10점 중 {{visibility}}점이야. 실력이 없다는 뜻이 아니라, 밖에서 확인할 통로가 없다는 뜻이야.","action":"14일 안에 민감정보를 지운 문제·해결·수치 사례를 한 편 공개해.","criticism":"시간이 해결해 준다는 기대는 계획이 아니야. 기다리는 동안 기록은 늘지 않아.","risk":"같은 행동을 반복하면 지금 막히는 지점이 그대로 남을 가능성이 높아.","scenario":"행동을 끝내고 성과로 입증하면 개선 경로를 다시 비교할 수 있어.","closing":"다음에는 의지 말고 완료한 증거를 기록해."}},{"id":"NO_RUNWAY","variant":"direct","headline":"준비 없는 퇴사는 선택지를 줄입니다.","judgement":"준비 없는 퇴사는 선택지를 줄입니다.","explanation":"생활비 여유가 {{runwayMonths}}개월입니다. 역할 변경을 검토하기 전에 버틸 수 있는 기간을 숫자로 확인해야 합니다.","criticism":"시간이 해결해 줄 거라는 기대는 실행 계획이 아닙니다.","risk":"같은 행동을 반복하면 현재 병목이 남을 수 있습니다.","recommendation":"선택할 수 있는 생활비를 확보하세요.","action":"이번 주 고정지출을 정리하고 6개월 비상자금 계획을 세우세요.","scenario":"행동을 완료하고 성과로 입증한다는 가정에서 개선 경로를 비교합니다.","closing":"다음 분석에서는 의지가 아니라 완료한 증거를 입력하세요.","direct":{"judgement":"준비 없이 나오면 선택지가 줄어.","explanation":"생활비 여유는 {{runwayMonths}}개월이야. 역할을 바꾸기 전에 버틸 수 있는 기간부터 숫자로 확인해.","action":"이번 주에 고정지출을 정리하고 6개월 비상자금 계획을 세워.","criticism":"시간이 해결해 준다는 기대는 계획이 아니야. 기다리는 동안 기록은 늘지 않아.","risk":"같은 행동을 반복하면 지금 막히는 지점이 그대로 남을 가능성이 높아.","scenario":"행동을 끝내고 성과로 입증하면 개선 경로를 다시 비교할 수 있어.","closing":"다음에는 의지 말고 완료한 증거를 기록해."}},{"id":"BUSINESS","variant":"direct","headline":"사업 아이디어보다 지불할 고객이 먼저입니다.","judgement":"사업 아이디어보다 지불할 고객이 먼저입니다.","explanation":"현재 고민은 창업입니다. 창업 관심과 실제 구매 의향은 다른 데이터입니다. 고객이 돈을 내는지부터 확인하세요.","criticism":"시간이 해결해 줄 거라는 기대는 실행 계획이 아닙니다.","risk":"같은 행동을 반복하면 현재 병목이 남을 수 있습니다.","recommendation":"퇴사 전에 고객부터 확인하세요.","action":"2주 동안 잠재 고객 10명을 인터뷰하고 유료 의향 3건을 확인하세요.","scenario":"행동을 완료하고 성과로 입증한다는 가정에서 개선 경로를 비교합니다.","closing":"다음 분석에서는 의지가 아니라 완료한 증거를 입력하세요.","direct":{"judgement":"아이디어보다 돈을 낼 고객이 먼저야.","explanation":"지금 고민은 창업이야. 창업에 관심이 있는 것과 고객이 실제로 지갑을 여는 건 다른 데이터야.","action":"2주 동안 잠재 고객 10명을 인터뷰하고 유료 의향 3건을 확인해.","criticism":"시간이 해결해 준다는 기대는 계획이 아니야. 기다리는 동안 기록은 늘지 않아.","risk":"같은 행동을 반복하면 지금 막히는 지점이 그대로 남을 가능성이 높아.","scenario":"행동을 끝내고 성과로 입증하면 개선 경로를 다시 비교할 수 있어.","closing":"다음에는 의지 말고 완료한 증거를 기록해."}},{"id":"MOVE","variant":"direct","headline":"회사 이름만 바꾸면 같은 한계를 만납니다.","judgement":"회사 이름만 바꾸면 같은 한계를 만납니다.","explanation":"현재 고민은 이직이고 총 경력은 {{experienceYears}}년입니다. 직장을 옮기는 목적을 연봉·역할·학습 중 하나로 명확하게 정하세요.","criticism":"시간이 해결해 줄 거라는 기대는 실행 계획이 아닙니다.","risk":"같은 행동을 반복하면 현재 병목이 남을 수 있습니다.","recommendation":"업무량 대신 결과를 기록하세요.","action":"이번 주 성과 3건을 전후 수치와 담당 범위로 정리하세요.","scenario":"행동을 완료하고 성과로 입증한다는 가정에서 개선 경로를 비교합니다.","closing":"다음 분석에서는 의지가 아니라 완료한 증거를 입력하세요.","direct":{"judgement":"회사 이름만 바꾸면 같은 한계를 다시 만나.","explanation":"지금 고민은 이직이고 총 경력은 {{experienceYears}}년이야. 옮기는 목적을 연봉·역할·학습 중 하나로 분명히 정해.","action":"이번 주에 성과 3건을 전후 수치와 담당 범위로 정리해.","criticism":"시간이 해결해 준다는 기대는 계획이 아니야. 기다리는 동안 기록은 늘지 않아.","risk":"같은 행동을 반복하면 지금 막히는 지점이 그대로 남을 가능성이 높아.","scenario":"행동을 끝내고 성과로 입증하면 개선 경로를 다시 비교할 수 있어.","closing":"다음에는 의지 말고 완료한 증거를 기록해."}},{"id":"PROMOTION","variant":"direct","headline":"승진을 기다리지 말고 상위 역할의 증거를 만드세요.","judgement":"승진을 기다리지 말고 상위 역할의 증거를 만드세요.","explanation":"현재 {{currentRoleLabel}}에서 다음 역할을 검토하고 있습니다. 상위 직급의 책임을 이미 수행한 사례가 있어야 협상이 구체적이 됩니다.","criticism":"시간이 해결해 줄 거라는 기대는 실행 계획이 아닙니다.","risk":"같은 행동을 반복하면 현재 병목이 남을 수 있습니다.","recommendation":"작은 팀의 결과를 책임지세요.","action":"30일 안에 3명 규모 프로젝트를 제안하고 역할과 마감일을 문서화하세요.","scenario":"행동을 완료하고 성과로 입증한다는 가정에서 개선 경로를 비교합니다.","closing":"다음 분석에서는 의지가 아니라 완료한 증거를 입력하세요.","direct":{"judgement":"승진을 기다리지 말고, 상위 역할의 증거부터 만들어.","explanation":"지금은 {{currentRoleLabel}}에서 다음 역할을 보고 있어. 상위 직급의 책임을 이미 해본 사례가 있어야 협상이 구체적으로 돼.","action":"30일 안에 3명 규모 프로젝트를 제안하고, 네 역할과 마감일을 문서로 남겨.","criticism":"시간이 해결해 준다는 기대는 계획이 아니야. 기다리는 동안 기록은 늘지 않아.","risk":"같은 행동을 반복하면 지금 막히는 지점이 그대로 남을 가능성이 높아.","scenario":"행동을 끝내고 성과로 입증하면 개선 경로를 다시 비교할 수 있어.","closing":"다음에는 의지 말고 완료한 증거를 기록해."}},{"id":"NETWORK","variant":"direct","headline":"필요할 때만 만드는 인맥은 늦습니다.","judgement":"필요할 때만 만드는 인맥은 늦습니다.","explanation":"직무 네트워크 입력은 10점 중 {{network}}점입니다. 공고 밖의 업무 정보와 피드백을 얻을 통로를 확보하세요.","criticism":"시간이 해결해 줄 거라는 기대는 실행 계획이 아닙니다.","risk":"같은 행동을 반복하면 현재 병목이 남을 수 있습니다.","recommendation":"연락할 사람을 만드세요.","action":"매주 동종 직무 1명과 업무 이야기를 나누고 배운 점을 기록하세요.","scenario":"행동을 완료하고 성과로 입증한다는 가정에서 개선 경로를 비교합니다.","closing":"다음 분석에서는 의지가 아니라 완료한 증거를 입력하세요.","direct":{"judgement":"필요할 때 만드는 인맥은 이미 늦어.","explanation":"직무 네트워크 입력은 10점 중 {{network}}점이야. 공고 밖의 정보와 피드백을 받을 통로를 만들어 둬.","action":"매주 같은 직무 한 명과 업무 이야기를 나누고 배운 걸 기록해.","criticism":"시간이 해결해 준다는 기대는 계획이 아니야. 기다리는 동안 기록은 늘지 않아.","risk":"같은 행동을 반복하면 지금 막히는 지점이 그대로 남을 가능성이 높아.","scenario":"행동을 끝내고 성과로 입증하면 개선 경로를 다시 비교할 수 있어.","closing":"다음에는 의지 말고 완료한 증거를 기록해."}},{"id":"LEARNING","variant":"direct","headline":"기존 기술의 유효기간을 점검하세요.","judgement":"기존 기술의 유효기간을 점검하세요.","explanation":"주당 학습 시간은 {{learningHours}}시간입니다. 시간을 더 쓰기 전에 배운 것을 결과물로 검증하는 주기를 정하세요.","criticism":"시간이 해결해 줄 거라는 기대는 실행 계획이 아닙니다.","risk":"같은 행동을 반복하면 현재 병목이 남을 수 있습니다.","recommendation":"학습을 일정에 고정하세요.","action":"4주간 주 3시간을 배정하고 매주 결과물로 검증하세요.","scenario":"행동을 완료하고 성과로 입증한다는 가정에서 개선 경로를 비교합니다.","closing":"다음 분석에서는 의지가 아니라 완료한 증거를 입력하세요.","direct":{"judgement":"지금 가진 기술의 유효기간부터 확인해.","explanation":"주당 학습 시간은 {{learningHours}}시간이야. 시간을 더 쓰기 전에 배운 걸 결과물로 검증하는 주기를 정해.","action":"4주 동안 주 3시간을 배정하고, 매주 결과물로 검증해.","criticism":"시간이 해결해 준다는 기대는 계획이 아니야. 기다리는 동안 기록은 늘지 않아.","risk":"같은 행동을 반복하면 지금 막히는 지점이 그대로 남을 가능성이 높아.","scenario":"행동을 끝내고 성과로 입증하면 개선 경로를 다시 비교할 수 있어.","closing":"다음에는 의지 말고 완료한 증거를 기록해."}},{"id":"JUNIOR","variant":"direct","headline":"지금 필요한 것은 넓은 관심보다 완수 경험입니다.","judgement":"지금 필요한 것은 넓은 관심보다 완수 경험입니다.","explanation":"초기 경력 {{experienceYears}}년 구간입니다. 지금은 새로운 분야를 계속 추가하기보다 하나의 일을 끝까지 완수한 기록이 필요합니다.","criticism":"시간이 해결해 줄 거라는 기대는 실행 계획이 아닙니다.","risk":"같은 행동을 반복하면 현재 병목이 남을 수 있습니다.","recommendation":"지원보다 먼저 작은 실무를 완주하세요.","action":"6주 안에 실제 사용자가 있는 프로젝트나 유급 단기 업무를 완수하세요.","scenario":"행동을 완료하고 성과로 입증한다는 가정에서 개선 경로를 비교합니다.","closing":"다음 분석에서는 의지가 아니라 완료한 증거를 입력하세요.","direct":{"judgement":"넓은 관심보다 끝까지 해낸 경험이 필요해.","explanation":"초기 경력 {{experienceYears}}년 구간이야. 지금은 분야를 계속 늘리는 것보다 하나를 끝까지 끝낸 기록이 필요해.","action":"6주 안에 실제 사용자가 있는 프로젝트나 유급 단기 업무를 하나 끝내.","criticism":"시간이 해결해 준다는 기대는 계획이 아니야. 기다리는 동안 기록은 늘지 않아.","risk":"같은 행동을 반복하면 지금 막히는 지점이 그대로 남을 가능성이 높아.","scenario":"행동을 끝내고 성과로 입증하면 개선 경로를 다시 비교할 수 있어.","closing":"다음에는 의지 말고 완료한 증거를 기록해."}},{"id":"SENIOR","variant":"direct","headline":"연차를 성과로 번역해야 합니다.","judgement":"연차를 성과로 번역해야 합니다.","explanation":"{{experienceYears}}년 경력을 갖고 있습니다. 담당 업무의 나열을 넘어 어떤 수치나 의사결정이 달라졌는지 설명해야 합니다.","criticism":"시간이 해결해 줄 거라는 기대는 실행 계획이 아닙니다.","risk":"같은 행동을 반복하면 현재 병목이 남을 수 있습니다.","recommendation":"업무량 대신 결과를 기록하세요.","action":"이번 주 성과 3건을 전후 수치와 담당 범위로 정리하세요.","scenario":"행동을 완료하고 성과로 입증한다는 가정에서 개선 경로를 비교합니다.","closing":"다음 분석에서는 의지가 아니라 완료한 증거를 입력하세요.","direct":{"judgement":"연차는 아직 성과로 번역되지 않았어.","explanation":"경력은 {{experienceYears}}년이야. 담당 업무를 나열하지 말고, 어떤 수치와 결정이 달라졌는지 설명할 수 있어야 해.","action":"이번 주에 성과 3건을 전후 수치와 담당 범위로 정리해.","criticism":"시간이 해결해 준다는 기대는 계획이 아니야. 기다리는 동안 기록은 늘지 않아.","risk":"같은 행동을 반복하면 지금 막히는 지점이 그대로 남을 가능성이 높아.","scenario":"행동을 끝내고 성과로 입증하면 개선 경로를 다시 비교할 수 있어.","closing":"다음에는 의지 말고 완료한 증거를 기록해."}},{"id":"IT","variant":"direct","headline":"기술 목록보다 사용된 결과물을 보여주세요.","judgement":"기술 목록보다 사용된 결과물을 보여주세요.","explanation":"Software / IT 직업군을 선택했습니다. 기술 이름을 나열하기보다 실제 사용한 맥락·제약·결과를 연결해 보여주세요.","criticism":"시간이 해결해 줄 거라는 기대는 실행 계획이 아닙니다.","risk":"같은 행동을 반복하면 현재 병목이 남을 수 있습니다.","recommendation":"직무를 하나 고르고 증거를 만드세요.","action":"30일 안에 목표 공고 10개를 비교하고 공통 기술로 결과물 1개를 완성하세요.","scenario":"행동을 완료하고 성과로 입증한다는 가정에서 개선 경로를 비교합니다.","closing":"다음 분석에서는 의지가 아니라 완료한 증거를 입력하세요.","direct":{"judgement":"기술 목록 말고 실제로 쓰인 결과물을 보여줘.","explanation":"Software / IT 직업군을 골랐어. 기술 이름을 늘어놓기보다 어떤 맥락과 제약에서 무엇이 달라졌는지 연결해서 보여줘.","action":"30일 안에 목표 공고 10개를 비교하고, 공통 기술로 결과물 하나를 완성해.","criticism":"시간이 해결해 준다는 기대는 계획이 아니야. 기다리는 동안 기록은 늘지 않아.","risk":"같은 행동을 반복하면 지금 막히는 지점이 그대로 남을 가능성이 높아.","scenario":"행동을 끝내고 성과로 입증하면 개선 경로를 다시 비교할 수 있어.","closing":"다음에는 의지 말고 완료한 증거를 기록해."}},{"id":"PRODUCT","variant":"direct","headline":"기획서가 아니라 실행 결과를 책임지세요.","judgement":"기획서가 아니라 실행 결과를 책임지세요.","explanation":"Product / Planning 직업군을 선택했습니다. 좋은 문서보다 실행에 참여한 사람과 실제 결과가 평가 근거가 됩니다.","criticism":"시간이 해결해 줄 거라는 기대는 실행 계획이 아닙니다.","risk":"같은 행동을 반복하면 현재 병목이 남을 수 있습니다.","recommendation":"작은 팀의 결과를 책임지세요.","action":"30일 안에 3명 규모 프로젝트를 제안하고 역할과 마감일을 문서화하세요.","scenario":"행동을 완료하고 성과로 입증한다는 가정에서 개선 경로를 비교합니다.","closing":"다음 분석에서는 의지가 아니라 완료한 증거를 입력하세요.","direct":{"judgement":"기획서가 아니라 실행 결과를 책임져.","explanation":"Product / Planning 직업군을 골랐어. 문서가 좋은 것보다 누가 같이 실행했고 실제로 뭐가 나왔는지가 평가 근거가 돼.","action":"30일 안에 3명 규모 프로젝트를 제안하고, 네 역할과 마감일을 문서로 남겨.","criticism":"시간이 해결해 준다는 기대는 계획이 아니야. 기다리는 동안 기록은 늘지 않아.","risk":"같은 행동을 반복하면 지금 막히는 지점이 그대로 남을 가능성이 높아.","scenario":"행동을 끝내고 성과로 입증하면 개선 경로를 다시 비교할 수 있어.","closing":"다음에는 의지 말고 완료한 증거를 기록해."}},{"id":"STUDENT","variant":"direct","headline":"졸업 전에 작은 실무를 경험하세요.","judgement":"졸업 전에 작은 실무를 경험하세요.","explanation":"학생 상태에서는 성적과 별도로 협업·마감·실사용 피드백을 경험한 작은 프로젝트가 필요합니다.","criticism":"시간이 해결해 줄 거라는 기대는 실행 계획이 아닙니다.","risk":"같은 행동을 반복하면 현재 병목이 남을 수 있습니다.","recommendation":"지원보다 먼저 작은 실무를 완주하세요.","action":"6주 안에 실제 사용자가 있는 프로젝트나 유급 단기 업무를 완수하세요.","scenario":"행동을 완료하고 성과로 입증한다는 가정에서 개선 경로를 비교합니다.","closing":"다음 분석에서는 의지가 아니라 완료한 증거를 입력하세요.","direct":{"judgement":"졸업 전에 작은 실무를 먼저 겪어.","explanation":"학생 구간에서는 성적과 별개로 협업·마감·실사용 피드백을 겪은 작은 프로젝트가 필요해.","action":"6주 안에 실제 사용자가 있는 프로젝트나 유급 단기 업무를 하나 끝내.","criticism":"시간이 해결해 준다는 기대는 계획이 아니야. 기다리는 동안 기록은 늘지 않아.","risk":"같은 행동을 반복하면 지금 막히는 지점이 그대로 남을 가능성이 높아.","scenario":"행동을 끝내고 성과로 입증하면 개선 경로를 다시 비교할 수 있어.","closing":"다음에는 의지 말고 완료한 증거를 기록해."}},{"id":"FREELANCE","variant":"direct","headline":"한 고객 의존도를 낮추세요.","judgement":"한 고객 의존도를 낮추세요.","explanation":"프리랜서에게는 단가뿐 아니라 다음 계약까지의 공백과 고객 집중도가 중요합니다. 연락 가능한 고객과 여유 자금을 함께 점검하세요.","criticism":"시간이 해결해 줄 거라는 기대는 실행 계획이 아닙니다.","risk":"같은 행동을 반복하면 현재 병목이 남을 수 있습니다.","recommendation":"연락할 사람을 만드세요.","action":"매주 동종 직무 1명과 업무 이야기를 나누고 배운 점을 기록하세요.","scenario":"행동을 완료하고 성과로 입증한다는 가정에서 개선 경로를 비교합니다.","closing":"다음 분석에서는 의지가 아니라 완료한 증거를 입력하세요.","direct":{"judgement":"한 고객에 걸린 비중을 낮춰.","explanation":"프리랜서는 단가보다 다음 계약까지의 공백과 고객 집중도가 더 위험해. 연락 가능한 고객과 여유 자금을 같이 점검해.","action":"매주 같은 직무 한 명과 업무 이야기를 나누고 배운 걸 기록해.","criticism":"시간이 해결해 준다는 기대는 계획이 아니야. 기다리는 동안 기록은 늘지 않아.","risk":"같은 행동을 반복하면 지금 막히는 지점이 그대로 남을 가능성이 높아.","scenario":"행동을 끝내고 성과로 입증하면 개선 경로를 다시 비교할 수 있어.","closing":"다음에는 의지 말고 완료한 증거를 기록해."}},{"id":"INCOME","variant":"direct","headline":"시간보다 성과의 가격을 설명하세요.","judgement":"시간보다 성과의 가격을 설명하세요.","explanation":"소득을 고민하고 있습니다. 투입한 시간과 고객·조직이 얻은 결과를 분리해 기록하고, 성과의 가격을 설명하세요.","criticism":"시간이 해결해 줄 거라는 기대는 실행 계획이 아닙니다.","risk":"같은 행동을 반복하면 현재 병목이 남을 수 있습니다.","recommendation":"협상 자료를 만드세요.","action":"30일 안에 시장 공고 10개와 본인 성과를 1장으로 정리하세요.","scenario":"행동을 완료하고 성과로 입증한다는 가정에서 개선 경로를 비교합니다.","closing":"다음 분석에서는 의지가 아니라 완료한 증거를 입력하세요.","direct":{"judgement":"들인 시간 말고 성과의 가격을 설명해.","explanation":"지금 고민은 소득이야. 투입한 시간과 고객·조직이 얻은 결과를 나눠서 기록하고, 그 결과의 가격을 설명해.","action":"30일 안에 시장 공고 10개와 네 성과를 한 장으로 정리해.","criticism":"시간이 해결해 준다는 기대는 계획이 아니야. 기다리는 동안 기록은 늘지 않아.","risk":"같은 행동을 반복하면 지금 막히는 지점이 그대로 남을 가능성이 높아.","scenario":"행동을 끝내고 성과로 입증하면 개선 경로를 다시 비교할 수 있어.","closing":"다음에는 의지 말고 완료한 증거를 기록해."}},{"id":"TRANSITION","variant":"direct","headline":"새 역할은 현직에 있을 때 검증하세요.","judgement":"새 역할은 현직에 있을 때 검증하세요.","explanation":"커리어 전환 또는 퇴직을 검토하고 있습니다. 새 역할을 작은 규모로 먼저 수행해 기대와 실제 업무의 차이를 확인하세요.","criticism":"시간이 해결해 줄 거라는 기대는 실행 계획이 아닙니다.","risk":"같은 행동을 반복하면 현재 병목이 남을 수 있습니다.","recommendation":"직무를 하나 고르고 증거를 만드세요.","action":"30일 안에 목표 공고 10개를 비교하고 공통 기술로 결과물 1개를 완성하세요.","scenario":"행동을 완료하고 성과로 입증한다는 가정에서 개선 경로를 비교합니다.","closing":"다음 분석에서는 의지가 아니라 완료한 증거를 입력하세요.","direct":{"judgement":"새 역할은 지금 자리에 있을 때 검증해.","explanation":"커리어 전환이나 퇴직을 보고 있어. 새 역할을 작은 규모로 먼저 해보고 기대와 실제 업무의 차이를 확인해.","action":"30일 안에 목표 공고 10개를 비교하고, 공통 기술로 결과물 하나를 완성해.","criticism":"시간이 해결해 준다는 기대는 계획이 아니야. 기다리는 동안 기록은 늘지 않아.","risk":"같은 행동을 반복하면 지금 막히는 지점이 그대로 남을 가능성이 높아.","scenario":"행동을 끝내고 성과로 입증하면 개선 경로를 다시 비교할 수 있어.","closing":"다음에는 의지 말고 완료한 증거를 기록해."}},{"id":"LEADER","variant":"direct","headline":"영향력을 반복 가능한 운영 구조로 바꾸세요.","judgement":"영향력을 반복 가능한 운영 구조로 바꾸세요.","explanation":"리더십 {{leadership}}점, 외부 가시성 {{external_visibility}}점으로 역할 확대의 기반이 있습니다. 이제 성과가 본인 없이도 반복되는지 확인하세요.","criticism":"시간이 해결해 줄 거라는 기대는 실행 계획이 아닙니다.","risk":"같은 행동을 반복하면 현재 병목이 남을 수 있습니다.","recommendation":"업무량 대신 결과를 기록하세요.","action":"이번 주 성과 3건을 전후 수치와 담당 범위로 정리하세요.","scenario":"행동을 완료하고 성과로 입증한다는 가정에서 개선 경로를 비교합니다.","closing":"다음 분석에서는 의지가 아니라 완료한 증거를 입력하세요.","direct":{"judgement":"영향력을 네가 없어도 도는 구조로 바꿔.","explanation":"리더십 {{leadership}}점, 외부 가시성 {{external_visibility}}점이야. 역할을 넓힐 기반은 있어. 이제 그 성과가 너 없이도 반복되는지 확인해.","action":"이번 주에 성과 3건을 전후 수치와 담당 범위로 정리해.","criticism":"시간이 해결해 준다는 기대는 계획이 아니야. 기다리는 동안 기록은 늘지 않아.","risk":"같은 행동을 반복하면 지금 막히는 지점이 그대로 남을 가능성이 높아.","scenario":"행동을 끝내고 성과로 입증하면 개선 경로를 다시 비교할 수 있어.","closing":"다음에는 의지 말고 완료한 증거를 기록해."}}],"sections":[{"id":"section_1","title":"타고난 직업 성향","key":"topTraits"},{"id":"section_2","title":"현재 직업 적합도","key":"fit"},{"id":"section_3","title":"무직인 경우 유력 직업군","key":"occupations"},{"id":"section_4","title":"조직형 / 전문가형 / 사업형","key":"orientation"},{"id":"section_5","title":"적합한 업무환경","key":"environment"},{"id":"section_6","title":"리더십 성향","key":"leadership"},{"id":"section_7","title":"돈을 버는 방식","key":"income"},{"id":"section_8","title":"조직생활 지속 가능성","key":"organization"},{"id":"section_9","title":"이직 성향","key":"mobility"},{"id":"section_10","title":"이직 검토 시기","key":"chang